{"command": "python3 - << 'PY'
# Define a simple arpeggio sequence (A major: A3, C#4, E4)
arp_notes = ["C#4", "E4", "A4"]
# Bass notes: A2, C#3, E3, A3
bass_notes = ["A2", "C#3", "E3", "A3"]

commands = []
# Arpeggio on channel 0 (Lead Square)
for i in range(16):
    note = arp_notes[i % len(arp_notes)]
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0,
            "row": i,
            "channel": 0,
            "note": note,
            "instrument": 1,
            "volume": 64
        }
    })

# Bass on channel 1 (Bass Pluck)
for i in range(16):
    note = bass_notes[i % len(bass_notes)]
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0,
            "row": i,
            "channel": 1,
            "note": note,
            "instrument": 2,
            "volume": 55
        }
    })

# Repeat arpeggio and bass for rows 16-31
for i in range(16,32):
    j = i - 16
    note = arp_notes[j % len(arp_notes)]
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0,
            "row": i,
            "channel": 0,
            "note": note,
            "instrument": 1,
            "volume": 64
        }
    })
    note = bass_notes[j % len(bass_notes)]
    commands.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0,
            "row": i,
            "channel": 1,
            "note": note,
            "instrument": 2,
            "volume": 55
        }
    })

# Noise FX stinger at row 31 on channel 7
commands.append({
    "name": "pattern_set_cell",
    "arguments": {
        "pattern": 0,
        "row": 31,
        "channel": 7,
        "note": "C-0",
        "instrument": 4,
        "volume": 64
    }
})

import json
print(json.dumps(commands, separators=(',', ':')))
PY
"}

